volatile bool eventReady = false;

void onButtonEdge() {
  eventReady = true;
}

void setup() {
  pinMode(2, INPUT_PULLUP);
  attachInterrupt(digitalPinToInterrupt(2), onButtonEdge, FALLING);
}

void loop() {
  if (eventReady) {
    noInterrupts();
    eventReady = false;
    interrupts();
    // Handle the event outside the interrupt.
  }
}
